USING (SELECT 'DMF0042' AS MNU_ID, 'Biz Plan' AS SHT_NM, 'SEARCH' AS MNU_BTN_CD FROM DUAL) S
ON (T.MNU_ID=S.MNU_ID AND T.SHT_NM=S.SHT_NM AND T.MNU_BTN_CD=S.MNU_BTN_CD)
